<article class="max-w-3xl mx-auto"><div class="text-xs uppercase tracking-wider text-[#ef6b4a] font-bold mb-5"><?=e($article['category_name']??'News')?></div><h1 class="display text-4xl md:text-6xl font-bold leading-tight"><?=e($article['title'])?></h1><div class="text-sm text-gray-500 mt-5 border-b pb-6">Published <?=e($article['published_at']??'')?> · Original reporting based on source material</div><?php if($article['featured_image']): ?><img src="<?=e($article['featured_image'])?>" alt="" class="w-full rounded-2xl mt-8 max-h-96 object-cover"><?php endif; ?><p class="text-xl text-gray-600 leading-relaxed mt-8"><?=e($article['summary'])?></p><div class="prose prose-lg max-w-none mt-8 whitespace-pre-line leading-relaxed"><?=e($article['content'])?></div><aside class="mt-12 rounded-2xl bg-[#e9f7c7] p-6"><div class="font-bold">Source attribution</div><p class="text-sm mt-2">Source: <?=e($article['source_name']??'Original source')?></p><?php if($article['source_url']): ?><a class="text-sm underline" target="_blank" rel="noopener noreferrer" href="<?=e($article['source_url'])?>">Read the original article →</a><?php endif; ?></aside><?php if($related): ?><section class="mt-12"><h2 class="display text-2xl font-bold mb-4">Related reporting</h2><div class="grid md:grid-cols-3 gap-4"><?php foreach($related as $r): ?><a href="/news/<?=e($r['slug'])?>" class="bg-white rounded-xl p-4 shadow-sm font-semibold"><?=e($r['title'])?></a><?php endforeach; ?></div></section><?php endif; ?></article>
